from pathlib import Path
import json,numpy as np,pandas as pd
R=Path(__file__).resolve().parent
def main():
    d=json.loads((R/'results/decision.json').read_text());a=pd.read_csv(R/'results/aggregate_metrics.csv');stress=json.loads((R/'results/software_stress.json').read_text());pairs=json.loads((R/'results/initialization_pairs.json').read_text());matrix=json.loads((R/'runtime/MATRIX.json').read_text());runs=[json.loads((R/'results'/f"{c['id']}_evaluation.json").read_text()) for c in matrix['cases'] if (R/'results'/f"{c['id']}_evaluation.json").exists()];native=[json.loads((R/'results'/f"{r['run']}_native.json").read_text()) for r in runs];outcomes=[json.loads((R/'runtime/results'/f"{r['run']}_outcome.json").read_text()) for r in runs];host=[json.loads((R/'runtime/results'/f"{r['run']}_host_result.json").read_text()) for r in runs];training=json.loads((R/'results/models/summary.json').read_text());validation=json.loads((R/'results/validation.json').read_text());wall=sum((x['end_monotonic_ns']-x['start_monotonic_ns'])*1e-9 for x in host)
    s=['# R6 冻结主干在线适应：实测报告','',f"完成 {len(runs)}/8 条有界 Gazebo 在线影子试验和一次未解锁检查。安全/数据门：{'全部通过' if d['safety_data_pass'] else '未全部通过'}；JEPA 预测收益门：{'通过' if d['jepa_prediction_release'] else '失败'}；学习控制放行：**否**。这次确实运行了在线小矩阵更新，不再只是离线训练或历史窗口推理，但仍未证明无需手调的负载动力学适应已经成功。",'', '## 可核对结果','',f"八槽累计墙钟 {wall:.1f} s（上限 1440 s）。七组影子方法在各次同一轨迹上运行；实际学习控制飞行为 0。所有网络文件及内存张量哈希保持不变，在线/离线最大预测差 {d['max_replay_difference']:.3g}。最大单次消息接收到处理延迟 P95 {d['max_latency_p95_ms']:.2f} ms；最大单模型推理+更新 P95 {d['max_core_p95_ms']:.3f} ms。延迟不含未测得的源发布到 DDS 接收部分，不能称完整硬实时保证。",'', '| 条件 | 安全/数据 | 独立任务位置 RMSE / 峰值 cm | 姿态 RMSE ° | 慢更新次数 / 秩 | 新最终 hover 门 |','|---|---|---:|---:|---:|---|']
    for r,n,o in zip(runs,native,outcomes):
        control=r['control']['task'];ad=r['online']['adapters']['jepa_17'];s.append(f"| {r['run']} | {'PASS' if o['continue_batch'] else 'FAIL'} | {control['position_rmse_m']*100:.2f} / {control['position_peak_m']*100:.2f} | {n['phases']['independent_task']['attitude_rmse_deg']:.3f} | {ad['updates']} / {ad['rank']} | {'PASS' if n['new_task_final_hover']['stable_final_1s'] else 'FAIL'} |")
    s += ['', '位置/姿态为既有控制器执行主动/常规参考时的结果，不是学习控制收益。新 hover 门检查 71–72 s；旧 oracle 恢复门仍未修复、未重验，二者不可互相替换。','位置诊断还发现：种子 2 的四条试验，从 45–48 s 到 71–72 s，真实机体 Y 位移为 −8.40～−8.85 cm，估计位置变化为 −3.59～−3.99 cm，二者变化相差约 +4.7～+4.9 cm。因此不能用较小的估计器跟踪误差掩盖真实漂移。这是相对位移诊断，不是绝对真值跟踪误差，也不能唯一归因于某个滤波器参数；详见 results/recovery_diagnosis.json。', '', '## 独立任务预测对照','', '表中为估计器标签，58–67.5 s 起点。单位分别为 m/s、rad/s。神经方法汇总三个模型种子、每条件两个仿真种子；对每条轨迹的 RMSE 作平方均值开方。它不是把滑窗或模型种子当独立飞行的显著性检验。所有时域都使用区间内实际收到的执行器指令，属于事后动作条件预测。','', '| 环境 | 方法 | 时域 ms | 主动：更新关 v / ω | 主动：更新开 v / ω | 常规：更新开 v / ω |','|---|---|---:|---:|---:|---:|']
    for family in ['mass','com']:
        for method in ['physics','supervised','jepa']:
            for h in [.1,.2,.4]:
                q=a[(a.family==family)&(a.method_group==method)&(a.phase=='independent_task')&(a.target=='estimator')&(a.horizon_s==h)];values=[]
                for exc,upd in [('active','off'),('active','on'),('conventional','on')]:
                    row=q[(q.excitation==exc)&(q['update']==upd)].iloc[0];values.append(f"{row.velocity_rmse_m_s:.5f} / {row.omega_rmse_rad_s:.5f}")
                s.append(f"| {family} | {method} | {h*1000:.0f} | "+' | '.join(values)+' |')
    s+=['','![预测对照](results/comparison.png)','','完整 100/200/400 ms、辨识/独立任务、估计器/真值绝对状态/真值增量的分组结果在 `results/all_metrics.csv`；各窗口原始误差 CSV 在本地复现包。真值从未参与训练标准化、模型选择或在线更新。','', '## 登记门槛与适应时间','']
    for g in d['prediction_gates']:
        if g['method']!='jepa':continue
        rr=g['ratios'];s.append(f"- {g['family']}：主动更新相对关闭，速度改善 {(1-rr['velocity_rmse_m_s_on_over_off'])*100:.2f}%，角速度改善 {(1-rr['omega_rmse_rad_s_on_over_off'])*100:.2f}%；主动相对常规更新，速度改善 {(1-rr['velocity_rmse_m_s_active_over_conventional'])*100:.2f}%，角速度改善 {(1-rr['omega_rmse_rad_s_active_over_conventional'])*100:.2f}%。登记判定 {'PASS' if g['passed'] else 'FAIL'}。")
    times=[x for r in runs for x in r['adaptation']];resolved=[x for x in times if x['first_sustained_2s_improvement_s'] is not None];s += ['',f"{len(resolved)}/{len(times)} 个方法×轨迹组合达到辨识窗内连续 2 s 的双指标≥10%改善，其余按 8 s 右删失报告，不虚构恢复时间。该口径只看更新前的滚动辨识误差，不代替独立任务泛化。每次辨识提供约 80 个区间，另有 10 s hover 标定预算。",'', '## 失败与限制定位','', '1. 首条主动质量试验回归协方差特征值约 0.0150、0.0284、0.9905、4.7069；门限 0.05 下只更新两个方向。最弱方向主要是垂向比力，次弱为滚转。姿态激励能量匹配不等于对质量/所有惯量充分激励。此秩是四维回归量的秩，不是八个物理参数的可辨识秩。',f"2. 合成残差脉冲压力测试：在辨识窗 51–53 s 给已记录标签添加峰值 0.3 m/s² 的短脉冲，最大持久 W 差 {max(x['persistent_W_difference'] for x in stress['rows']):.5f}。这是软件敏感性测试，不是真实风仿真；结果说明中心化和固定更新窗仍不能保证瞬态扰动不写入慢系数。",'3. 旧训练动作只来自 20 Hz 快照；新测试逐回调动作通常更密。没有用无法获得的原生动作填补旧数据。名义倾转角来自固定 80/100 ms 观测器，未验证未知舵机动态。', '4. W 只修正物理状态读出，不反馈到潜空间转移；未训练环境潜变量或元学习支持/查询适应。被冻结的网络不等于完整环境条件化世界模型。', '5. 标签为估计器状态，Gazebo 真值只独立评价。估计器偏差可能被学入模型；完整表同时给真值绝对和增量误差。低估计器误差不能直接作为物理准确性或控制价值证明。', '6. 旧 oracle 接口仍存在整体位置恢复失败；本轮不把平均残差直接反号送入加速度端口，也没有靠放松该门来解锁控制。控制链原零路径和 9 项限幅/回退测试通过，只证明守住关闭状态。', '7. 本轮未知环境仅两类、每类两种噪声种子；未新增惯量/舵机、飞行中参数阶跃、真实风或组合测试。未达到初始收益与扰动隔离要求，因此不扩大训练或进入学习控制试验。', '', '## 公平性、实现与溯源','', f"离线训练四条完整轨迹 1980 窗口，验证一条 495 窗口。六个模型各 8382 参数，固定 24 epoch，训练合计 {sum(m['wall_s'] for m in training['models']):.2f} s。神经方法同结构/数据/优化步数，JEPA 的未来编码/非塌缩计算使实际计算量更大，不宣称 FLOP 完全匹配。模型/损失/输入输出/24系数及10个初始化统计量详见 [MODEL_zh.md](MODEL_zh.md)。", f"主动/常规同 8 s、同最大角度界限，解析采样积分的指令角能量均约 {runs[0]['commanded_angle_energy_rad2_s']:.9f} rad²·s。{sum(x['comparison']['passed'] for x in pairs)}/{len(pairs)} 配对通过已有起始状态统计匹配门；仍不是同一全状态分叉。",'首条 post-run 的 NumPy 布尔序列化和更新窗口起止端点误用已修复；原失败验收与停止记录保存在 audit_repairs，没有重飞、换种子或改变模型。见 [AMENDMENTS_zh.md](AMENDMENTS_zh.md)。','原 Controller/PX4 的 HEAD 和 14 个既有脏文件哈希未变。无实机、无 remote 配置更改、无强推。原始日志保留本机；交付前逐文件散列，包内文件重新打开验证。复现步骤见 [REPRODUCE_zh.md](REPRODUCE_zh.md)。','','## 与论文的关系','','[Neural-Fly](https://arxiv.org/html/2205.06908v2) 已使用离线表示与在线小系数适应；本轮没有复现其组合自适应律及稳定性证明，不能把这个大方向称首创。','[T2-z](https://arxiv.org/html/2610.22364v1) 的冻结模型/测试环境潜变量优化为慢适应提供参考；本实现是读出矩阵，并未实现其环境潜变量训练。','[ReDRAW](https://arxiv.org/html/2504.02252v1) 研究冻结世界模型上的潜空间动态残差；本轮没有替换为其想象轨迹/RL策略。','[SkyJEPA](https://arxiv.org/html/2606.23444v2) 的动作条件潜预测、非塌缩和物理读出是结构参考；论文规划器可以提供候选未来动作，本 PX4 链路不能据此假设未来执行器动作已知。','','下一步应先补充垂向/执行器可辨识性与扰动隔离证据、重建动作采样一致的训练集，并独立修复与重验 oracle 整体控制门；当前结果不支持继续加大 JEPA 训练来宣称闭环收益。']
    (R/'REPORT_zh.md').write_text('\n'.join(s)+'\n');print('report written')
if __name__=='__main__':main()
